"""Attentuator tool base"""
from builtins import object
from abc import ABCMeta, abstractmethod
from future.utils import with_metaclass


class ToolBase(with_metaclass(ABCMeta, object)):
    """Attentuator tool base"""

    TOOL = None

    @abstractmethod
    def attenuator_setup(self, device):
        """Attenuator setup"""
        pass

    @abstractmethod
    def attenuator_configure(self, operation, **kwargs):
        """Attenuator configure"""
        pass

    @abstractmethod
    def attenuator_teardown(self):
        """Attenuator teradown"""
        pass

    @classmethod
    def check_tool(cls, tool):
        """Check tool"""
        return tool == cls.TOOL
